// Basic String Output
printf("Hello, World!\n");

// Variable Output (Format Specifiers)
int x = 10;
float pi = 3.14159;
char c = 'A';
printf("Int: %d, Float: %.2f, Char: %c\n", x, pi, c);

// Width and Alignment
printf("|%10s|%-5d|\n", "Text", 123);

// Hexadecimal and Pointer
unsigned int hex = 0xFF;
void* p = &x;
printf("Hex: 0x%X, Pointer: %p\n", hex, p);
